// Valida y normaliza la query entrante
const body = $input.item.json.body || $input.item.json;
const query = (body.query || '').trim();
const topK = body.top_k || 3;
const categoria = body.categoria || null;

if (!query) {
  throw new Error('El campo "query" es obligatorio');
}

return { query, top_k: topK, categoria };

// Construye el SQL completo con el embedding inline (evita el bug de queryReplacement con comas)
const params = $('Validar query').item.json;
const embeddingResp = $input.item.json;
const embedding = embeddingResp.data?.[0]?.embedding;

if (!embedding) {
  throw new Error('No se pudo generar embedding de la query');
}

function escString(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

const embedLiteral = "'[" + embedding.join(',') + "]'::vector";
const categoriaFilter = params.categoria
  ? `WHERE categoria = ${escString(params.categoria)}`
  : '';
const topK = parseInt(params.top_k, 10) || 3;

const sql = `SELECT
  id,
  slug,
  categoria,
  nombre,
  descripcion_corta,
  descripcion_larga,
  precio_setup,
  precio_recurrente,
  tiempo_entrega,
  entregables,
  casos_uso,
  prerequisitos,
  1 - (embedding <=> ${embedLiteral}) AS similarity
FROM kb_servicios
${categoriaFilter}
ORDER BY embedding <=> ${embedLiteral}
LIMIT ${topK};`;

return { sql, query: params.query };

// Recolecta todos los resultados (cada item es una fila) y los retorna como array
const items = $input.all();
const query = $('Validar query').item.json.query;

const resultados = items.map(it => ({
  id: it.json.id,
  slug: it.json.slug,
  categoria: it.json.categoria,
  nombre: it.json.nombre,
  descripcion_corta: it.json.descripcion_corta,
  descripcion_larga: it.json.descripcion_larga,
  precio_setup: it.json.precio_setup,
  precio_recurrente: it.json.precio_recurrente,
  tiempo_entrega: it.json.tiempo_entrega,
  entregables: it.json.entregables,
  casos_uso: it.json.casos_uso,
  prerequisitos: it.json.prerequisitos,
  similarity: it.json.similarity
}));

return {
  ok: true,
  query,
  total: resultados.length,
  resultados
};
